// Pedido de la web: { mensaje, historial: [{rol, texto}], adjunto: {base64, nombre, mime} }
const h = $input.first().json.headers || {};
if ((h['x-api-key'] || '') !== $env.N8N_WEBHOOK_TOKEN) throw new Error('No autorizado: falta o es incorrecto el header X-API-Key');
const b = $input.first().json.body || $input.first().json;
const msg = String(b.mensaje || b.message || '').trim();
const hist = (Array.isArray(b.historial) ? b.historial : []).slice(-8);
const histTxt = hist.map(h => `${h.rol === 'usuario' ? 'Usuario' : 'Asistente'}: ${String(h.texto || '').slice(0, 2000)}`).join('\n\n');
const original = histTxt
  ? `Conversación previa (contexto; respondé solo el pedido actual):\n${histTxt}\n\nPedido actual del usuario: ${msg}`
  : msg;
const a = b.adjunto;
const adjunto = a && a.base64 ? { base64: a.base64, nombre: a.nombre || 'archivo', mime: a.mime || '' } : null;
const contexto = histTxt ? `Conversación previa (respondé solo el pedido actual):
${histTxt}` : '';
return [{ json: { agent: 'orquestador', prompt: msg, contexto, mensaje_original: original, mensaje_usuario: msg, complejidad: 'compleja', adjunto,
  session_id: b.session_id ? String(b.session_id) : null } }];

// Suma el texto del adjunto al pedido
const pedido = $('Preparar pedido').first().json;
// Resultado de la herramienta MCP leer_archivo: {archivo, tipo, truncado, texto}
const r = $input.first().json;
const sc = r.structuredContent;
const a = (sc && (sc.result || sc)) || r.content?.[0]?.text || {};
const textoAdjunto = `Archivo adjunto "${a.archivo}" (${a.tipo}${a.truncado ? ', recortado' : ''}):\n${a.texto}`;
return [{ json: { ...pedido, adjunto: null, textoAdjunto, prompt: `${pedido.mensaje_original}\n\n${textoAdjunto}` } }];

// Convierte el plan JSON del orquestador en un ítem por subtarea.
const VALIDOS = ['general','agentic_ai','fisica_robotica','vision','entrenamiento_inferencia','datos_optimizacion','gpu_dev','infra_redes','salud_ciencias'];
const original = $('Preparar pedido').first().json.mensaje_original;
let adjunto = '';
try { adjunto = $('Agregar texto del adjunto').first().json.textoAdjunto || ''; } catch (e) {}
const r = $input.first().json;
let plan = [];
try {
  const txt = String(r.output || '').replace(/```(json)?/g, '');
  const m = txt.match(/\{[\s\S]*\}/);
  plan = JSON.parse(m ? m[0] : txt).plan || [];
} catch (e) {}
plan = plan.filter(p => VALIDOS.includes(p.agente)).slice(0, 3);
if (!plan.length) plan = [{ agente: 'general', tarea: original, complejidad: 'simple' }];
// slot: posición entre las subtareas del mismo agente, para repartirlas entre los modelos locales
const vistos = {};
// Documentos e informes con gráficos siempre como "compleja" (los modelos locales chicos arman mal los datos)
const DOC = /\b(pdf|word|docx|excel|xlsx|planilla|informe|reporte|gr[aá]fico|markdown|documento)s?\b/i;
// Búsquedas y navegación web también (encadenan varias llamadas a herramientas)
const WEB = /\b(busc[aáeé]\w*|web|internet|naveg\w*|captur\w*|screenshot|sitio|p[aá]gina|precio|cotizaci[oó]n|noticia)s?\b|https?:\/\//i;
return plan.map(p => ({ json: {
  agent: p.agente,
  prompt: p.tarea,
  complejidad: p.complejidad === 'simple' && !DOC.test(`${p.tarea} ${original}`) && !WEB.test(`${p.tarea} ${original}`) ? 'simple' : 'compleja',
  slot: (vistos[p.agente] = (vistos[p.agente] ?? -1) + 1),
  session_id: $('Preparar pedido').first().json.session_id || null,
  contexto: `Pedido original del usuario: ${original}` + (adjunto ? `\n\n${adjunto}` : ''),
} }));

const original = $('Preparar pedido').first().json.mensaje_original;
const res = $input.all().map(i => i.json);
const err = r => r.output || (r.error ? `Error: ${r.error.message || JSON.stringify(r.error)}` : 'sin respuesta');
// Con un solo agente que respondió bien no hace falta sintetizar
if (res.length === 1 && res[0].ok) {
  return [{ json: { saltar: true, directo: res[0].output } }];
}
const partes = res.map(r => `### ${r.agent || '?'} (modelo: ${r.model || 'ninguno'})
Tarea: ${r.tarea || ''}

${err(r)}`).join('

---

');
return [{ json: { saltar: false, agent: 'sintesis', complejidad: 'compleja', prompt: `Pedido original:
${original}

Respuestas de los agentes:

${partes}` } }];

const esp = $('Ejecutar agentes en paralelo').all().map(i => i.json);
const j = $json;
const final = j.saltar ? j.directo : (j.ok ? j.output : esp.map(e => e.output || '').join('\n\n'));
const pie = esp.map(e => `${e.agent || '?'} → ${e.model || 'sin modelo'}${e.fallos_previos?.length ? ` (${e.fallos_previos.length} fallback)` : ''}`).join(' · ');
const sint = j.saltar ? '' : ` · síntesis → ${j.model || 'n/a'}`;
const pp = $('Preparar pedido').first().json;
const original = pp.mensaje_usuario || pp.mensaje_original;
const titulo = original.length > 90 ? original.slice(0, 87) + '...' : original;
return [{ json: { output: `${final}\n\n---\n_Agentes: ${pie}${sint}_`, titulo: titulo || 'Respuesta' } }];

// Arma el pedido para el verificador: lo que pidió el usuario + la respuesta final (sin el pie de agentes)
const pp = $('Preparar pedido').first().json;
const respuesta = String($json.output || '').replace(/\n+---\n_Agentes:[\s\S]*$/, '');
let adjunto = '';
try { adjunto = $('Agregar texto del adjunto').first().json.textoAdjunto || ''; } catch (e) {}
const pedido = pp.mensaje_usuario || pp.mensaje_original;
return [{ json: {
  agent: 'verificador',
  complejidad: 'compleja',
  session_id: pp.session_id || null,
  prompt: `PEDIDO DEL USUARIO:\n${pedido}\n\nRESPUESTA A REVISAR:\n${respuesta}`,
  // Conversación previa (pedidos de seguimiento como "agregale gráficos") y adjunto, para entender qué se pidió
  contexto: [pp.mensaje_original !== pedido ? pp.mensaje_original : '', adjunto ? adjunto.slice(0, 3000) : ''].filter(Boolean).join('\n\n'),
} }];

// Lee el veredicto del verificador. Si falta algo, arma el pedido de corrección para el agente principal.
// Si el verificador falla o no devuelve JSON, se da por cumplido (la revisión nunca bloquea la respuesta).
const v = $input.first().json;
let r = { cumple: true, faltantes: [], instruccion: '' };
try {
  const m = String(v.output || '').replace(/```(json)?/g, '').match(/\{[\s\S]*\}/);
  if (m) r = { ...r, ...JSON.parse(m[0]) };
} catch (e) {}
const faltantes = (Array.isArray(r.faltantes) ? r.faltantes : []).map(String).filter(f => f.trim()).slice(0, 6);
const cumple = r.cumple !== false || !faltantes.length;

const pp = $('Preparar pedido').first().json;
const previa = String($('Respuesta final').first().json.output || '').replace(/\n+---\n_Agentes:[\s\S]*$/, '');
// Corrige el agente que hizo la parte principal (el primero que respondió bien)
const esp = $('Ejecutar agentes en paralelo').all().map(i => i.json).filter(e => e.ok);
const agente = (esp[0] && esp[0].agent) || 'general';
return [{ json: {
  cumple, faltantes, instruccion: String(r.instruccion || ''), verificador: v.model || null,
  agent: agente, complejidad: 'compleja', fase: 'correccion', session_id: pp.session_id || null,
  prompt: `Tu respuesta anterior NO cumple todo lo que pidió el usuario.
Falta:
${faltantes.map(f => `- ${f}`).join('\n')}
${r.instruccion ? `Cómo completarlo: ${r.instruccion}\n` : ''}
Respuesta anterior:
${previa}

Devolvé la respuesta COMPLETA y corregida (no solo lo que falta). Si faltan archivos, gráficos, diagramas o capturas,
generalos con las herramientas y copiá los links nuevos tal cual.`,
  contexto: `Pedido original del usuario: ${pp.mensaje_original}`,
} }];

// Respuesta final después de la revisión: la corregida si hizo falta completar algo, si no la original
const base = $('Respuesta final').first().json;
const ev = $('Evaluar verificación').first().json;
const pie = (String(base.output).match(/\n+---\n_Agentes:[\s\S]*$/) || [''])[0];
let output = base.output;
const verificacion = { cumple: ev.cumple, faltantes: ev.faltantes, corregido: false, modelo: ev.verificador };
if (!ev.cumple) {
  const c = $json;  // lo que devolvió el agente al completar
  if (c.ok && String(c.output || '').trim()) {
    output = String(c.output).trim() + (pie ? pie.replace(/_\s*$/, ` · revisión → completó ${c.agent} con ${c.model}_`) : '');
    verificacion.corregido = true;
  } else {
    output = `${base.output}\n\n> ⚠️ La revisión indica que podría faltar: ${ev.faltantes.join('; ')}`;
  }
}
return [{ json: { output, titulo: base.titulo, verificacion } }];

// Respuesta JSON para la web
const base = $('Respuesta revisada').first().json;
const esp = $('Ejecutar agentes en paralelo').all().map(i => i.json);
return [{ json: {
  ok: true,
  respuesta: base.output,
  titulo: base.titulo,
  html_url: $json.html_url || null,
  verificacion: base.verificacion || null,
  agentes: esp.map(e => ({ agente: e.agent || '?', modelo: e.model || null, proveedor: e.proveedor || null, ok: !!e.ok })),
} }];
